function validate([root, result]) {
  if (typeof result !== 'boolean') return 'result must be true or false.';
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 100000) return 'The tree has at most 100000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 5)) return 'Every node value is between 0 and 5.';
  // Walk the level order to count each node's children.
  const nodes = [root[0]];
  let next = 1;
  for (let q = 0; q < nodes.length; q++) {
    let children = 0;
    for (let side = 0; side < 2 && next < root.length; side++) {
      const v = root[next++];
      if (v !== null) { nodes.push(v); children++; }
    }
    const val = nodes[q];
    if (children === 0 && val > 1) return 'A leaf must hold 0 or 1.';
    if (children > 0 && val < 2) return 'A node with children must hold an operator from 2 to 5.';
    if (val === 5 && children !== 1) return 'A NOT node (5) has exactly one child.';
    if (val >= 2 && val <= 4 && children !== 2) return 'OR, AND and XOR nodes (2, 3, 4) have exactly two children.';
  }
  return null;
}

