function minimumFlips(root, result) {
  // cost(node) returns [flips to make it false, flips to make it true].
  function cost(node) {
    if (node.left === null && node.right === null) {
      return node.val === 1 ? [1, 0] : [0, 1];
    }
    if (node.val === 5) {
      const [toFalse, toTrue] = cost(node.left ?? node.right);
      return [toTrue, toFalse];
    }
    const left = cost(node.left);
    const right = cost(node.right);
    const best = [Infinity, Infinity];
    for (let a = 0; a <= 1; a++) {
      for (let b = 0; b <= 1; b++) {
        const value = node.val === 2 ? a | b : node.val === 3 ? a & b : a ^ b;
        best[value] = Math.min(best[value], left[a] + right[b]);
      }
    }
    return best;
  }

  return cost(root)[result ? 1 : 0];
}

