function minimumFlips(root, result) {
  const leaves = [];
  const collect = node => {
    if (!node) return;
    if (!node.left && !node.right) leaves.push(node);
    collect(node.left);
    collect(node.right);
  };
  collect(root);
  const evaluate = (node, flipped) => {
    if (!node.left && !node.right) return flipped.has(node) ? 1 - node.val : node.val;
    if (node.val === 5) return 1 - evaluate(node.left || node.right, flipped);
    const x = evaluate(node.left, flipped), y = evaluate(node.right, flipped);
    if (node.val === 2) return x || y ? 1 : 0;
    if (node.val === 3) return x && y ? 1 : 0;
    return x === y ? 0 : 1;
  };
  const want = result ? 1 : 0;
  let fewest = Infinity;
  for (let mask = 0; mask < 1 << leaves.length; mask++) {
    const flipped = new Set(leaves.filter((_, i) => mask >> i & 1));
    if (flipped.size < fewest && evaluate(root, flipped) === want) fewest = flipped.size;
  }
  return fewest;
}

