function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 13);
  const notRate = rand() * 0.4;
  // Lopsided trees put almost everything on one side, which makes them deep.
  const lopsided = rand() < 0.3;
  const build = count => {
    if (count === 1) return { val: rand() < 0.5 ? 0 : 1, left: null, right: null };
    const node = { val: 5, left: null, right: null };
    if (count === 2 || rand() < notRate) {
      node[rand() < 0.5 ? 'left' : 'right'] = build(count - 1);
      return node;
    }
    node.val = 2 + Math.floor(rand() * 3);
    const leftCount = lopsided ? (rand() < 0.5 ? 1 : count - 2) : 1 + Math.floor(rand() * (count - 2));
    node.left = build(leftCount);
    node.right = build(count - 1 - leftCount);
    return node;
  };
  const tree = build(n);
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [tree];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (node === null) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out, rand() < 0.5];
}
